    {
      "card_ids": ["C33"],
      "claim": "Absolute oral bioavailability of GSK1322322 1500 mg tablet was 77% in fed healthy volunteers, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Brigatinib oral bioavailability was estimated at 46% in healthy volunteers, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Linezolid demonstrated 100% absolute oral bioavailability in patients, strongly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Rifapentine absolute oral bioavailability was 70% in healthy adult volunteers, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Paliperidone extended-release absolute oral bioavailability was 28% in healthy volunteers, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Encainide absolute oral bioavailability was 32 ± 7% in normal subjects, above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple independent human absolute oral bioavailability measurements for related molecules are consistently at or above 20% (28–100%), outweighing the uncertain physicochemical prior that predicted low absorption; therefore the query is predicted to have high oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule itself; all evidence is from analogue molecules.",
    "Query structure is omitted, so structural similarity to the high-bioavailability analogues cannot be directly verified.",
    "The physicochemical prior suggests low neutral fraction and high polar surface area, but no experimental permeability or solubility data for the query are available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

